// AutoMiningDrones 1.1.0
const autoMiningDrones = require("./autoMiningDrones").create({
  context(session) {
    const id = toInt(session && (session.characterID || session.charid), 0);
    if (!id || findSessionByCharacterID(id) !== session || session.stationid || session.stationID) return null;
    const state = getShipStateForSession(session);
    if (!state || state.shipEntity.mode === "WARP" || state.shipEntity.warpState) return null;
    return state;
  },
  drones: state => listControlledDroneEntities(state.scene, state.shipRecord.itemID),
  family: classifyDroneMiningYieldKind,
  idle: (drone, state) => resetDroneToIdle(drone, state.shipEntity, { scene: state.scene, stopMovement: true }),
  drone: (state, id) => state.scene.getEntityByID(id),
  eligible(drone, state) {
    return isDroneEntity(drone) && toInt(drone.controllerID, 0) === toInt(state.shipRecord.itemID, 0) &&
      !!classifyDroneMiningYieldKind(drone) && !getDronePilotAssignment(drone) &&
      !drone.droneSalvage && !drone.droneRepair &&
      getEntitySurfaceDistance(drone, state.shipEntity, state.scene, null, "automining-control") <= 20000;
  },
  targets(state) {
    const cache = ensureSceneMiningState(state.scene);
    if (!cache || !(cache.byEntityID instanceof Map)) return [];
    return [...cache.byEntityID.values()].filter(m => toNumber(m.remainingQuantity, 0) > 0)
      .map(m => state.scene.getEntityByID(m.entityID)).filter(Boolean);
  },
  allowed(drone, target, state) {
    const mineable = getMineableState(state.scene, target.itemID);
    return !!mineable && toNumber(mineable.remainingQuantity, 0) > 0 &&
      isDroneMiningCompatibleWithTarget(drone, mineable) &&
      canPlayerCompanionActOnTarget(state.scene, findSessionByCharacterID(state.characterID), drone, state.shipEntity, target) &&
      getEntitySurfaceDistance(state.shipEntity, target, state.scene, null, "automining-target") <= 20000;
  },
  distance: (drone, target, state) => getEntitySurfaceDistance(drone, target, state.scene, null, "automining-nearest"),
  full(state, drone, target = null) {
    const storage = state.autoMiningStorage || resolveShipStorageSnapshotForDrone(state.shipEntity);
    if (!storage) return false;
    state.autoMiningStorage = storage;
    const mineable = getMineableState(state.scene, target ? target.itemID : drone.targetID);
    const ice = classifyDroneMiningYieldKind(drone) === "ice";
    const yieldID = toInt(mineable && mineable.yieldTypeID, ice ? 16264 : 1230);
    // Watch the preferred mining hold itself. Do not spill into ordinary cargo
    // when a ship has a dedicated ore/ice/mining hold that is full.
    const flag = getPreferredMiningHoldFlagForType(storage.resourceState, yieldID) || ITEM_FLAGS.CARGO_HOLD;
    const unit = Math.max(0.000001, toNumber(mineable && mineable.unitVolume, ice ? 1000 : 0.1));
    return getAvailableDroneStorageVolume(storage, flag) + 1e-9 < unit;
  },
  mine: commandMineRepeatedly,
  recall: commandReturnBay,
  notify(session, message) { session.sendNotification("OnRemoteMessage", "clientID", ["CustomNotify", { type: "dict", entries: [["notify", message]] }]); },
  error(error) { log.warn("[AutoMiningDrones] Automation disabled: " + String(error && error.message || error)); },
});

module.exports = {
  autoMiningDronesCommand: autoMiningDrones.command,

